const dictionary = STRINGS[CONFIG.locale] ?? STRINGS.ar;
const pluralRules = new Intl.PluralRules(CONFIG.locale);

function lookup(path) {
  return path.split('.').reduce((node, key) => (node == null ? undefined : node[key]), dictionary);
}

function interpolate(value, params) {
  if (typeof value === 'string') {
    return value.replace(/\{(\w+)\}/g, (match, key) => (params[key] ?? match));
  }
  if (Array.isArray(value)) return value.map((item) => interpolate(item, params));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, interpolate(item, params)]));
  }
  return value;
}

/**
 * Translate a dotted key. Returns a string, or an interpolated object/array
 * when the key points at a group (e.g. an error's {title, detail, why, next}).
 */
export function t(path, params = {}) {
  const value = lookup(path);
  if (value === undefined) {
    console.warn(`[i18n] Missing key: ${path}`);
    return path;
  }
  return interpolate(value, params);
}

/** Pluralised string using the locale's CLDR rules (Arabic has six forms). */
export function tPlural(path, count, params = {}) {
  const forms = lookup(path) ?? {};
  const form = forms[pluralRules.select(count)] ?? forms.other ?? path;
  return interpolate(form, { n: count, ...params });
}

export const LOCALE = CONFIG.locale;
